<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {RouterLink} from 'vue-router'
import Icon from './Icon.vue'
import type {ControlOverview,ControlPlan,PlanResult} from '../api/greenhouseControl'
import {clone,zoneLabel,parametersText,localTime,statusLabel} from '../greenhouse/control'
const props=defineProps<{overview:ControlOverview;plans:ControlPlan[];busy:boolean;modelReady:boolean;capabilityError:string;frameId:string|null;preferred:string}>()
const emit=defineEmits<{generate:[stage:string,horizon:number,frame:string|null];save:[plan:ControlPlan,result:PlanResult];confirm:[plan:ControlPlan,ids:string[]];cancel:[plan:ControlPlan]}>()
const planId=ref(''),stage=ref('出苗展叶期'),horizon=ref(120),useFrame=ref(true),draft=ref<PlanResult|null>(null),selected=ref<string[]>([]),editing=ref('')
watch(()=>props.frameId,value=>{useFrame.value=!!value},{immediate:true})
const plan=computed(()=>props.plans.find(v=>v.id===planId.value)??props.plans[0]??null)
watch(()=>props.preferred,id=>{if(id)planId.value=id})
watch(()=>[plan.value?.id,plan.value?.revision],()=>{draft.value=plan.value?.result?clone(plan.value.result):null;selected.value=draft.value?.actions.map(a=>a.id)??[];editing.value='';if(plan.value)planId.value=plan.value.id},{immediate:true})
const working=computed(()=>props.plans.some(v=>['queued','generating'].includes(v.status)))
const dirty=computed(()=>JSON.stringify(draft.value)!==JSON.stringify(plan.value?.result??null))
const stale=computed(()=>!!plan.value&&(plan.value.snapshot.epoch!==props.overview.epoch||plan.value.snapshot.design_revision!==props.overview.design_revision||new Date(plan.value.expires_at).getTime()<=Date.now()||props.overview.design_stale))
const editable=computed(()=>plan.value?.status==='draft'&&!stale.value&&!props.overview.paused&&!props.busy)
const monitoring=computed(()=>plan.value?.snapshot.monitoring??null)
const device=(id:string)=>props.overview.devices.find(d=>d.id===id)
function selectAll(event:Event){selected.value=(event.target as HTMLInputElement).checked?draft.value?.actions.map(a=>a.id)??[]:[]}
</script>
<template>
 <section class="control-panel plan-panel" aria-label="AgriSeek 控制计划">
  <header class="panel-heading"><h2><Icon name="chart"/>AgriSeek 控制计划</h2><span class="tag">{{plan?statusLabel(plan.status):'按需生成'}}</span><button class="primary generate" :disabled="busy||working||!modelReady||overview.paused||overview.design_stale" @click="emit('generate',stage,horizon,useFrame?frameId:null)"><Icon name="play"/>{{working?'正在生成计划…':'生成控制计划'}}</button></header>
  <div class="plan-settings"><label>生长阶段<select v-model="stage" :disabled="busy||working"><option>出苗展叶期</option><option>开花结果期</option><option>根部生长期</option><option>枯萎休眠期</option></select></label><label>计划范围<select v-model.number="horizon" :disabled="busy||working"><option :value="60">未来 1 小时</option><option :value="120">未来 2 小时</option><option :value="360">未来 6 小时</option><option :value="1440">未来 24 小时</option></select></label><label class="frame-choice"><input v-model="useFrame" type="checkbox" :disabled="!frameId||busy||working">使用当前监测快照</label><RouterLink v-if="!frameId" to="/live">前往监测</RouterLink></div>
  <div class="plan-data"><span><Icon name="humidity"/>外部气象 · {{monitoring?'已绑定快照':frameId&&useFrame?'待绑定':'未绑定'}}</span><span><Icon name="thermometer"/>棚内温度 · {{monitoring?'模型估算':'未绑定'}}</span><span><Icon name="gear"/>设备状态 · 模拟</span><span><Icon name="sprout"/>土壤水分 · 未接入</span></div>
  <div class="plan-history"><p class="muted">结合可用数据和设备配置，生成可编辑的控制草案。</p><label v-if="plans.length">计划记录<select v-model="planId" aria-label="计划记录"><option v-for="p in plans" :key="p.id" :value="p.id">{{localTime(p.created_at)}} · {{statusLabel(p.status)}}</option></select></label></div>
  <p v-if="capabilityError||!modelReady" class="notice">{{capabilityError||'AgriSeek 尚未配置，手动控制和定时任务仍可使用。'}}</p>
  <p v-if="stale&&plan?.status==='draft'" class="notice" role="status">计划已过期，或设备与配置已变化，请重新生成。</p>
  <div v-if="working&&!draft" class="plan-empty" role="status"><Icon name="chart"/><strong>AgriSeek 正在分析可用数据</strong><span>切换页面后任务仍会继续，返回即可查看结果。</span><button v-if="plan&&['queued','generating'].includes(plan.status)" :disabled="busy" @click="emit('cancel',plan)">取消生成</button></div>
  <p v-else-if="plan?.status==='failed'" class="notice" role="status">本次计划未生成，未创建任何执行任务。请检查服务状态后重新生成。</p>
  <template v-if="draft&&plan">
   <p class="plan-summary">{{draft.summary}}</p>
   <div v-if="draft.actions.length" class="control-table-wrap plan-table"><table><thead><tr><th><input aria-label="全选计划动作" type="checkbox" :checked="selected.length===draft.actions.length" :disabled="!editable" @change="selectAll"></th><th>设备 / 分区</th><th>建议动作</th><th>执行时间</th><th>分析依据</th><th>操作</th></tr></thead><tbody><template v-for="a in draft.actions" :key="a.id"><tr><td><input v-model="selected" :value="a.id" type="checkbox" :aria-label="`选择${device(a.device_id)?.name??'设备'}动作`" :disabled="!editable"></td><td>{{device(a.device_id)?.name??'设备已变化'}}<small>{{zoneLabel(device(a.device_id)?.zone_key??'all')}}</small></td><td>{{parametersText(a.parameters)}}</td><td>{{a.start_after_minutes?`确认后 ${a.start_after_minutes} 分钟`:'确认后执行'}}</td><td class="reason">{{a.reason}}</td><td><button class="text-button" :disabled="!editable" @click="editing=editing===a.id?'':a.id">{{editing===a.id?'收起':'编辑'}}</button></td></tr>
   <tr v-if="editing===a.id"><td colspan="6"><div class="plan-action-editor"><label>运行时长 / 秒<input v-model.number="a.parameters.duration_seconds" type="number" min="1" :max="device(a.device_id)?.capabilities.max_duration_seconds" aria-label="动作运行秒数"><small>单位：秒</small></label><label>确认后延迟 / 分钟<input v-model.number="a.start_after_minutes" type="number" min="0" :max="plan.input.horizon_minutes-1"></label><label v-if="a.parameters.speed">风速<select v-model="a.parameters.speed"><option value="low">低</option><option value="medium">中</option><option value="high">高</option></select></label><label v-if="a.parameters.brightness_percent">亮度 / %<input v-model.number="a.parameters.brightness_percent" type="number" min="1" max="100"></label><label class="wide">分析依据<textarea v-model="a.reason" maxlength="700" rows="2"/></label></div></td></tr></template></tbody></table></div>
   <p v-else class="notice">本次没有生成设备动作，请参考分析与待核查条件。</p>
   <details class="plan-evidence"><summary>查看分析依据与数据快照</summary><div class="evidence-scroll"><p>阶段：{{plan.input.stage}} · 数据固定于 {{localTime(plan.snapshot.captured_at)}}</p><p v-if="monitoring">外部温度 {{monitoring.bg_temp}} °C · 相对湿度 {{monitoring.bg_rh??'未知'}}% · 室外估算光照 {{monitoring.bg_light}} lux</p><p v-if="monitoring">气象时刻 {{localTime(monitoring.source.observed_at??monitoring.observed_at)}} · 光照来源时刻 {{localTime(monitoring.source.light_time)}}</p><p v-if="monitoring">棚内模型估温：均值 {{monitoring.summary.mean??'未知'}} °C，范围 {{monitoring.summary.vmin??'未知'}} 至 {{monitoring.summary.vmax??'未知'}} °C。</p><ul><li v-for="(note,i) in draft.notes" :key="i">{{note}}</li></ul><p>土壤水分与冠层实测光照未接入；模拟分组不代表分区实测。</p></div></details>
   <footer class="plan-footer"><span class="muted">确认后才创建任务，计划不会直接控制设备。</span><div><button v-if="plan.status==='draft'" :disabled="!editable||!dirty" @click="emit('save',plan,draft)">保存草案</button><button class="primary" :disabled="!editable||dirty||!selected.length" @click="emit('confirm',plan,selected)">{{plan.status==='confirmed'?'已创建任务':`确认并创建 ${selected.length} 项任务`}}</button></div></footer><p v-if="dirty" class="muted">草案已修改，请先保存再确认。</p>
  </template>
  <div v-else-if="!working&&plan?.status!=='failed'" class="plan-empty"><Icon name="chart"/><strong>{{plan?.status==='cancelled'?'本次计划已取消':'准备生成您的控制计划'}}</strong><span>选择阶段与范围，点击生成；也可先使用手动控制。</span></div>
 </section>
</template>
<style scoped>
.plan-panel .panel-heading{gap:10px}.panel-heading svg{color:var(--edge)}.generate{margin-left:auto}.plan-settings{display:flex;gap:22px;align-items:center;flex-wrap:wrap;padding:16px 0;border-bottom:1px solid var(--edge-line)}.plan-settings label{display:flex;align-items:center;gap:12px;font-size:13px}.plan-settings select{min-width:145px}.plan-settings .frame-choice{margin-left:auto;font-size:12px;color:var(--ink-muted);gap:5px}.plan-settings>a{font-size:12px}.plan-data{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:17px 0}.plan-data>span{display:flex;align-items:center;justify-content:center;gap:8px;padding:12px 8px;border:1px solid var(--edge-line);border-radius:5px;font-size:12px;background:var(--card-2);white-space:nowrap}.plan-data svg{width:20px;height:20px;color:var(--edge)}.plan-history{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:12px}.plan-history p{margin:0;font-size:12px}.plan-history label{display:flex;align-items:center;gap:8px;font-size:12px}.plan-history select{max-width:230px;font-size:12px}.plan-summary{font-size:14px;line-height:1.8;max-height:100px;overflow:auto;white-space:pre-wrap}.plan-empty{min-height:150px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;color:var(--ink-muted);font-size:13px;text-align:center}.plan-empty>svg{width:32px;height:32px;color:var(--edge)}.plan-empty>strong{font-weight:500;color:var(--ink)}.plan-table{max-height:430px;overflow:auto}table{min-width:760px}.reason{max-width:360px;min-width:170px;white-space:normal;line-height:1.7}td small{display:block;color:var(--ink-muted);margin-top:4px}.plan-action-editor{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;padding:12px;background:var(--card-2)}.plan-action-editor label{display:flex;flex-direction:column;gap:7px}.plan-action-editor input{width:100%}.plan-action-editor .wide{grid-column:1/-1}.plan-evidence{margin-top:15px;color:var(--ink-muted);font-size:12px}.plan-evidence summary{cursor:pointer;color:var(--edge)}.evidence-scroll{max-height:180px;overflow:auto;line-height:1.8;padding-right:10px;overscroll-behavior:contain}.plan-footer{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-top:20px;font-size:12px}.plan-footer>div{display:flex;gap:10px}.plan-footer button{white-space:nowrap}@media(max-width:1050px){.plan-data{grid-template-columns:repeat(2,minmax(0,1fr))}.plan-settings{gap:12px}.plan-settings .frame-choice{margin-left:0}.plan-history{flex-wrap:wrap}}@media(max-width:640px){.panel-heading{flex-wrap:wrap}.generate{width:100%}.plan-settings select{min-width:0}.plan-settings{gap:14px}.plan-footer{flex-direction:column;align-items:stretch}.plan-footer>div{justify-content:flex-end}.plan-action-editor{grid-template-columns:1fr 1fr}.plan-data{gap:7px}.plan-data>span{font-size:11px;padding:9px 5px}}
</style>
